    # Repeated short column motifs in a two-row band can continue into blank space.
    candidates = []
    for r in range(h-1):
        last = max((c for c in range(w) if grid[r][c] != bg or grid[r+1][c] != bg), default=-1)
        if last < 0 or last >= w-2:
            continue
        for p in range(2, min(6, w//2+1)):
            for t in range(w-p):
                if t + p <= last or t > last:
                    continue
                sig = tuple((grid[r][c], grid[r+1][c]) for c in range(t, t+p))
                if not any(a != bg or b != bg for a,b in sig):
                    continue
                # A matching motif must occur earlier in a two-row band.
                found = False
                for rr in range(h-1):
                    for s in range(w-p+1):
                        if rr == r and s >= t:
                            continue
                        other = tuple((grid[rr][c], grid[rr+1][c]) for c in range(s,s+p))
                        if other == sig:
                            found = True
                            break
                    if found: break
                if found and t+p <= w-2:
                    candidates.append((p,t,r,sig,last))
    if candidates:
        p,t,r,sig,last = max(candidates, key=lambda x:(x[0],x[1],x[2]))
        for c in range(t+p, w):
            a,b=sig[(c-t)%p]
            if grid[r][c] == bg and a != bg: out[r][c]=1
            if grid[r+1][c] == bg and b != bg: out[r+1][c]=1
    # Horizontal one-color bars continue as 1s to the right edge.
    for r,row in enumerate(grid):
        if row[0] == bg: continue
        last=max((c for c,v in enumerate(row) if v != bg),default=-1)
        if last>0 and all(row[c]==row[0] for c in range(last+1)) and last<w-1:
            for c in range(last+1,w): out[r][c]=1
    return out
